+        for i in 1..8 {
+            table[i] = table[i - 1] + base2;
+        }
+        return table;
+    }
+
+    let zz = base2.z.square();
+    let step = AffinePoint {
+        x: base2.x,
+        y: base2.y,
+        infinity: false,
+    };
+    let mut entry = ProjectivePoint {
+        x: base.x * zz,
+        y: base.y * (zz * base2.z),
+        z: base.z,
+    };
